// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Subscription.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(subscription.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *SubscriptionUpsertBulk) UpdateNewValues() *SubscriptionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(subscription.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(subscription.FieldCreatedAt)
			}
			if _, exists := b.mutation.ProfileID(); exists {
				s.SetIgnore(subscription.FieldProfileID)
			}
			if _, exists := b.mutation.ProfileType(); exists {
				s.SetIgnore(subscription.FieldProfileType)
			}
			if _, exists := b.mutation.OwnerUserID(); exists {
				s.SetIgnore(subscription.FieldOwnerUserID)
			}
			if _, exists := b.mutation.PlanCode(); exists {
				s.SetIgnore(subscription.FieldPlanCode)
			}
			if _, exists := b.mutation.Interval(); exists {
				s.SetIgnore(subscription.FieldInterval)
			}
			if _, exists := b.mutation.Channel(); exists {
				s.SetIgnore(subscription.FieldChannel)
			}
			if _, exists := b.mutation.WithTrial(); exists {
				s.SetIgnore(subscription.FieldWithTrial)
			}
		}
	}))
	return u
}

